<div class="intro-line"><p>Berita, agenda, regulasi, galeri, dan tautan sosial dikelola melalui satu meja redaksi. Hanya konten berstatus tayang muncul di portal publik.</p><?php if ($can_create): ?><a class="button button-dark" href="<?= site_url('admin/konten/tambah') ?>">+ Tulis konten</a><?php endif; ?></div>
<section class="panel table-panel"><form class="filterbar" method="get" action="<?= site_url($path) ?>"><label class="search-field"><span>Cari konten</span><input type="search" name="q" value="<?= h($p['q']) ?>" placeholder="Judul atau ringkasan"></label><label><span>Kategori</span><select name="category"><option value="">Semua</option><?php foreach ($categories as $c): ?><option value="<?= $c['id'] ?>" <?= (string)$category===(string)$c['id']?'selected':'' ?>><?= h($c['name']) ?></option><?php endforeach; ?></select></label><label><span>Status</span><select name="status"><option value="">Semua</option><?php foreach ($statuses as $code=>$name): ?><option value="<?= $code ?>" <?= $p['status']===$code?'selected':'' ?>><?= h($name) ?></option><?php endforeach; ?></select></label><label><span>Per halaman</span><select name="per_page"><?php foreach (array(10,25,50,100) as $n): ?><option value="<?= $n ?>" <?= $p['per_page']===$n?'selected':'' ?>><?= $n ?></option><?php endforeach; ?></select></label><button class="button button-dark button-small">Terapkan</button><a class="button button-quiet button-small" href="<?= site_url($path) ?>">Reset</a></form><div class="table-wrap"><table><thead><tr><th>Judul</th><th>Kategori</th><th>Status</th><th>Terbit</th><th>Aksi</th></tr></thead><tbody><?php foreach ($rows as $r): ?><tr><td><strong><?= h($r['title']) ?></strong></td><td><?= h($r['category_name']) ?></td><td><span class="pill <?= $r['status']==='published'?'pill-green':'pill-muted' ?>"><?= h($statuses[$r['status']]??$r['status']) ?></span></td><td><?= $r['published_at']?h(date('d M Y',strtotime($r['published_at']))):'—' ?></td><td><a class="row-link" href="<?= site_url('admin/konten/'.$r['id'].'/ubah') ?>">Ubah →</a><?php if ($r['status']==='published'): ?> · <a class="row-link" target="_blank" rel="noopener" href="<?= site_url('informasi/'.$r['slug']) ?>">Lihat ↗</a><?php endif; ?></td></tr><?php endforeach; ?><?php if (!$rows): ?><tr><td colspan="5" class="empty-cell">Belum ada konten yang sesuai filter.</td></tr><?php endif; ?></tbody></table></div><?php $this->load->view('partials/pagination'); ?></section>
